  window.addEventListener('load', () => {
    const link = document.querySelector('.header > a');
    const svg = link?.querySelector('svg');
    const letters = [...(svg?.querySelectorAll('[data-logo-letter], [data-logo-seal]') || [])];

    if (!link || !letters.length || !window.gsap) return;

    const motion = gsap.timeline({ paused: true });

    letters.forEach((letter) => {
      const delay = (letter.getBBox().x / 152) * 0.3;

      motion
        .to(
          letter,
          {
            y: -3.8,
            rotation: -5,
            transformOrigin: '50% 75%',
            duration: 0.28,
            ease: 'power2.inOut',
          },
          delay,
        )
        .to(
          letter,
          {
            y: 0,
            rotation: 0,
            duration: 0.58,
            ease: 'power3.out',
          },
          delay + 0.28,
        );
    });

    link.addEventListener('mouseenter', () => {
      if (!motion.isActive()) motion.restart();
    });

    link.addEventListener('focus', () => {
      if (!motion.isActive()) motion.restart();
    });
  });","[WORK]","[Commercials]","[Long Format]","[DIRECTORS]","[CLIENTS]","[LOCATIONS]","[ABOUT]","[ENG]","[CONTACT US]"],"h1":[],"fonts":["Neue Haas Grotesk Display Pro"],"bodyBg":"rgb(0, 0, 0)","darkScore":null}

